sys_ux_data_broker_transform.script:
function transform(input) {
    function fetchKPIs(propertyName, data, pageNo, recordsPerPage, searchTerm) {
        var page = parseInt(pageNo, 10) || 1;
        var perPage = parseInt(recordsPerPage, 10) || 20;
        var filteredData = data;

        if (searchTerm && searchTerm.trim() !== "") {
            gs.print("Search filter applied for term: " + searchTerm);
            filteredData = [];
            for (var i = 0; i < data.length; i++) {
                var record = data[i];
                var values = Object.keys(record);

                for (var j = 0; j < values.length; j++) {
                    var value = String(record[values[j]]).toLowerCase();
                    if (value.indexOf(searchTerm.toLowerCase()) !== -1) {
                        filteredData.push(record);
                        break; // Avoid adding the same record multiple times
                    }
                }
            }
        }

        var kpis = [];
        var propertyValue = gs.getProperty(propertyName);

        if (propertyValue) {
            try {
                kpis = JSON.parse(propertyValue);
            } catch (e) {
                gs.log("Error parsing " + propertyName + ": " + e.message);
            }
        } else {
            gs.log("Property " + propertyName + " is not set or is empty.");
        }
        return kpis;
    }

    try {
        var propertyName = input.propertyName;
        var pageNo = parseInt(input.pageNo, 10) || 1;
        var recordsPerPage = parseInt(input.recordsPerPage, 10) || 20;
        var searchTerm = input.searchTerm || '';

        var property = fetchKPIs(propertyName);

        // Validate property
        if (!property || !property.tableName || !property.fields) {
            gs.print("Invalid Property Format");
            return "Invalid Property Format";
        }

        var tableName = property.tableName;
        var gr = new GlideRecord(tableName);

        // Apply query if specified in property
        if (property.query) {
            gr.addEncodedQuery(property.query);
        }

        gr.query();

        // First, get all records and store them
        var allRecords = [];
        var propertyFields = property.fields;

        while (gr.next()) {
            var record = {};
            for (var key in propertyFields) {
                record[key] = gr.getDisplayValue(propertyFields[key]);
            }
            allRecords.push(record);
        }

        // Apply search filter if searchTerm exists
        var filteredRecords = allRecords;
        if (searchTerm && searchTerm.trim() !== "") {
            filteredRecords = [];
            for (var i = 0; i < allRecords.length; i++) {
                var record = allRecords[i];
                var values = Object.keys(record);

                for (var j = 0; j < values.length; j++) {
                    var value = String(record[values[j]]).toLowerCase();
                    if (value.indexOf(searchTerm.toLowerCase()) !== -1) {
                        filteredRecords.push(record);
                        break;
                    }
                }
            }
        }

        // Apply pagination to filtered results
        var totalCount = filteredRecords.length;
        var startIndex = (pageNo - 1) * recordsPerPage;
        var endIndex = Math.min(startIndex + recordsPerPage, totalCount);
        var paginatedRecords = filteredRecords.slice(startIndex, endIndex);

        // Log the output (for debugging)
        gs.print("Total Records: " + totalCount);
        gs.print("Retrieved Records: " + JSON.stringify(paginatedRecords, null, 2));

        // Return the paginated filtered records
        return {
            records: paginatedRecords,
            totalCount: totalCount,
            pageNo: pageNo,
            recordsPerPage: recordsPerPage
        };

    } catch (e) {
        gs.error("Error retrieving records from " + tableName + ": " + e.message);
        return "Error retrieving records from " + tableName;	
    }
}
